import{_ as e,r as n,o,c,e as s,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const h=JSON.parse('{"title":"Модульное тестирование - October CMS - 3.x","titleTemplate":false,"description":"Программно тестируйте и укрепляйте вашу бизнес-логику.","frontmatter":{"subtitle":"Программно тестируйте и укрепляйте вашу бизнес-логику."},"headers":[{"level":2,"title":"Создание тестов плагина","slug":"создание-тестов-плагина","link":"#создание-тестов-плагина","children":[]},{"level":2,"title":"Создание тестового класса","slug":"создание-тестового-класса","link":"#создание-тестового-класса","children":[]},{"level":2,"title":"Регистрация и загрузка плагинов","slug":"регистрация-и-загрузка-плагинов","link":"#регистрация-и-загрузка-плагинов","children":[]},{"level":2,"title":"Работа с базой данных","slug":"работа-с-базои-данных","link":"#работа-с-базои-данных","children":[{"level":3,"title":"Изменение базы данных","slug":"изменение-базы-данных","link":"#изменение-базы-данных","children":[]}]}],"relativePath":"3.x/ru/extend/system/unit-testing.md","filePath":"3.x/ru/extend/system/unit-testing.md"}'),i={name:"3.x/ru/extend/system/unit-testing.md"};function k(r,a,g,d,m,q){const t=n("pre-heading"),p=n("post-heading");return o(),c("div",null,[s(t),a[0]||(a[0]=l("h1",null,"Модульное тестирование",-1)),s(p),a[1]||(a[1]=u(`<p>Тестовые случаи отдельных плагинов можно выполнять с помощью artisan-команды <code>plugin:test</code>, за которой следует код плагина. Например, следующая команда запустит тесты, найденные в директории <strong>plugins/acme/demo</strong>.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan plugin:test acme.demo
</code></pre></div><div class="custom-block tip"><p>Если у вас установлен <code>phpunit</code> глобально, вы также можете вызвать его из директории плагина.</p></div><h2 id="создание-тестов-плагина"><a href="#создание-тестов-плагина" class="header-anchor">#</a> Создание тестов плагина</h2><p>Первый шаг к тестированию плагинов — создание файла <strong>phpunit.xml</strong> в базовой директории плагина. Вот пример файла с именем <strong>/plugins/acme/blog/phpunit.xml</strong> для плагина <code>Acme.Blog</code>.</p><div class="language-xml extra-class"><pre class="language-xml"><code><span class="token prolog">&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>phpunit</span>
    <span class="token attr-name">backupGlobals</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>false<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">backupStaticAttributes</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>false<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">bootstrap</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>../../../modules/system/tests/bootstrap.php<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">colors</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>true<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">convertErrorsToExceptions</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>true<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">convertNoticesToExceptions</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>true<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">convertWarningsToExceptions</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>true<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">processIsolation</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>false<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">stopOnFailure</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>false<span class="token punctuation">&quot;</span></span>
<span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>testsuites</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>testsuite</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Plugin Test Suite<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>directory</span><span class="token punctuation">&gt;</span></span>./tests<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>directory</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>exclude</span><span class="token punctuation">&gt;</span></span>./tests/browser<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>exclude</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>testsuite</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>testsuites</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>php</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>env</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>APP_ENV<span class="token punctuation">&quot;</span></span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>testing<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>env</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>CACHE_DRIVER<span class="token punctuation">&quot;</span></span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>array<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>env</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>SESSION_DRIVER<span class="token punctuation">&quot;</span></span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>array<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>env</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>ACTIVE_THEME<span class="token punctuation">&quot;</span></span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>test<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>env</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>CONVERT_LINE_ENDINGS<span class="token punctuation">&quot;</span></span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>true<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>env</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>CMS_ROUTE_CACHE<span class="token punctuation">&quot;</span></span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>true<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>env</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>CMS_TWIG_CACHE<span class="token punctuation">&quot;</span></span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>false<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>env</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>ENABLE_CSRF<span class="token punctuation">&quot;</span></span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>false<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>env</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>DB_CONNECTION<span class="token punctuation">&quot;</span></span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>sqlite<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>env</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>DB_DATABASE<span class="token punctuation">&quot;</span></span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>:memory:<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>php</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>phpunit</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="создание-тестового-класса"><a href="#создание-тестового-класса" class="header-anchor">#</a> Создание тестового класса</h2><p>Команда <code>create:test</code> генерирует тестовый класс. Первый аргумент указывает имя автора и плагина. Второй аргумент указывает имя тестового класса, которое должно заканчиваться на <strong>Test</strong>.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan create:test Acme.Blog UserTest
</code></pre></div><p>Все тесты должны быть размещены в директории <strong>tests</strong>, которая используется для хранения тестовых классов. Имена классов должны использовать суффикс <code>Test</code>, а пространство имён для класса является необязательным. Тестовый класс должен наследовать базовый класс <code>PluginTestCase</code> — это специальный класс, который настраивает базу данных October CMS в памяти в рамках метода <code>setUp</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Post</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">PostTest</span> <span class="token keyword">extends</span> <span class="token class-name">PluginTestCase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">testCreateFirstPost</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Hi!&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">assertEquals</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">id</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="регистрация-и-загрузка-плагинов"><a href="#регистрация-и-загрузка-плагинов" class="header-anchor">#</a> Регистрация и загрузка плагинов</h2><p>В тестовой среде сам плагин и все его зависимости регистрируются и загружаются автоматически. Это обеспечивает более точный контроль над тестовой средой и предотвращает вмешательство других плагинов в систему, например при регистрации событий. Вы можете отключить автоматическую загрузку текущего плагина, установив свойство <code>autoRegister</code> в <code>false</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">/**
 * @var bool autoRegister feature disabled for this test.
 */</span>
<span class="token keyword">protected</span> <span class="token variable">$autoRegister</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы можете вручную зарегистрировать и загрузить плагин с помощью метода <code>loadPlugin</code>. В некоторых случаях вам также потребуется выполнить миграцию плагина вручную (см. ниже).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">setUp</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token keyword return-type">void</span>
<span class="token punctuation">{</span>
    <span class="token keyword static-context">parent</span><span class="token operator">::</span><span class="token function">setUp</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Runs register() and boot() methods</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">loadPlugin</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme.Blog&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Доступны следующие методы регистрации.</p><div class="table"><table tabindex="0"><thead><tr><th>Имя метода</th><th>Назначение</th></tr></thead><tbody><tr><td><strong>loadAllPlugins()</strong></td><td>Загружает все плагины, найденные в системе.</td></tr><tr><td><strong>loadCurrentPlugin()</strong></td><td>Загружает текущий плагин и его зависимости.</td></tr><tr><td><strong>loadPlugin($code)</strong></td><td>Загружает один плагин по его коду, например: <code>Acme.Blog</code>.</td></tr><tr><td><strong>loadPlugins($codes)</strong></td><td>Загружает несколько плагинов как массив кодов.</td></tr></tbody></table></div><h2 id="работа-с-базои-данных"><a href="#работа-с-базои-данных" class="header-anchor">#</a> Работа с базой данных</h2><p>По умолчанию тесты плагинов автоматически выполняют миграции таблиц базы данных для модулей ядра, текущего плагина и его зависимостей. Это эквивалентно выполнению следующего перед каждым тестом.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan october:migrate
php artisan plugin:refresh Acme.Blog
<span class="token punctuation">[</span>php artisan plugin:refresh <span class="token operator">&lt;</span>dependency<span class="token operator">&gt;</span>, <span class="token punctuation">..</span>.<span class="token punctuation">]</span>
</code></pre></div><p>Вы можете отключить эту функцию, установив свойство <code>autoMigrate</code> в false в тестовом классе. Это применимо, когда тест не использует базу данных.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">PostTest</span> <span class="token keyword">extends</span> <span class="token class-name">PluginTestCase</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * @var bool autoMigrate feature disabled for this test.
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$autoMigrate</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Вы можете вручную выполнить миграцию плагинов с помощью метода <code>migratePlugin</code> при настройке теста. Метод <code>migrateModules</code> также может быть использован для создания системных таблиц.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">setUp</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token keyword return-type">void</span>
<span class="token punctuation">{</span>
    <span class="token keyword static-context">parent</span><span class="token operator">::</span><span class="token function">setUp</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Migrate core modules</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">migrateModules</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Migrate the blog plugin</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">migratePlugin</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme.Blog&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Доступны следующие методы миграции.</p><div class="table"><table tabindex="0"><thead><tr><th>Имя метода</th><th>Назначение</th></tr></thead><tbody><tr><td><strong>migrateDatabase()</strong></td><td>Выполняет миграцию всей базы данных, аналогично <code>october:migrate</code>.</td></tr><tr><td><strong>migrateModules()</strong></td><td>Выполняет миграцию только модулей ядра.</td></tr><tr><td><strong>migrateCurrentPlugin()</strong></td><td>Выполняет миграцию текущего плагина и его зависимостей.</td></tr><tr><td><strong>migratePlugin($code)</strong></td><td>Выполняет миграцию конкретного плагина по его коду, например: <code>Acme.Blog</code>.</td></tr></tbody></table></div><h3 id="изменение-базы-данных"><a href="#изменение-базы-данных" class="header-anchor">#</a> Изменение базы данных</h3><p>По умолчанию модульные тесты используют SQLite в памяти для тестовой среды плагина. Вы можете изменить эту настройку в файле <code>phpunit.xml</code>. Значения здесь основаны на конфигурационном файле <code>/config/database.php</code>.</p><div class="language-xml extra-class"><pre class="language-xml"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>env</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>DB_CONNECTION<span class="token punctuation">&quot;</span></span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>sqlite<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>env</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>DB_DATABASE<span class="token punctuation">&quot;</span></span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>:memory:<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div>`,30))])}const b=e(i,[["render",k]]);export{h as __pageData,b as default};
